def parser(log: str) -> dict[str, str]:
    import json
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def record(name: str, status: str) -> None:
        if not name:
            return
        results[name] = status

    def norm(value) -> str:
        return str(value or "").strip().upper()

    def has_nonzero(value) -> bool:
        if value is None:
            return False
        if isinstance(value, (int, float)):
            return value != 0
        if isinstance(value, str):
            return value.strip() not in {"", "0", "0.0"}
        if isinstance(value, (list, dict, tuple, set)):
            return len(value) > 0
        return False

    def status_from_test(test: dict) -> str:
        skip_markers = {"SKIP", "SKIPPED", "NOTRUN", "DISABLED", "SUPPRESSED", "IGNORED", "XFAIL"}
        fail_markers = {"FAIL", "FAILED", "ERROR", "TIMEOUT", "CRASHED", "ABORTED", "NOTOK", "XPASS"}

        status = norm(test.get("status"))
        result = norm(test.get("result"))

        skip = False
        fail = False

        if status in skip_markers or result in skip_markers:
            skip = True

        if any(marker in status for marker in fail_markers) or any(marker in result for marker in fail_markers):
            fail = True

        for key in ("disabled", "skipped"):
            if has_nonzero(test.get(key)):
                skip = True

        for key in ("failures", "errors", "failure", "error"):
            if has_nonzero(test.get(key)):
                fail = True

        if skip:
            return "skip"
        if fail:
            return "fail"
        return "pass"

    def walk_suite(suite: dict, parent_name: str = "") -> None:
        suite_name = suite.get("name") or suite.get("classname") or suite.get("class") or parent_name

        # If this dict itself looks like a test case
        if (
            "name" in suite
            and any(k in suite for k in ("status", "result", "failures", "errors", "skipped", "disabled"))
            and not any(k in suite for k in ("testsuite", "testsuites", "testcase", "testcases"))
        ):
            classname = suite.get("classname") or suite.get("class") or parent_name
            name = suite.get("name", "")
            full_name = f"{classname}.{name}" if classname else name
            record(full_name, status_from_test(suite))

        for key in ("testsuite", "testsuites", "testcase", "testcases", "cases", "tests"):
            items = suite.get(key)
            if isinstance(items, list):
                for item in items:
                    if not isinstance(item, dict):
                        continue
                    if any(k in item for k in ("testsuite", "testsuites", "testcase", "testcases")):
                        walk_suite(item, suite_name)
                    elif "name" in item:
                        classname = item.get("classname") or item.get("class") or suite_name
                        name = item.get("name", "")
                        full_name = f"{classname}.{name}" if classname else name
                        record(full_name, status_from_test(item))

    def iter_json_objects(text: str):
        decoder = json.JSONDecoder()
        idx = 0
        length = len(text)
        while idx < length:
            match = re.search(r"[\{\[]", text[idx:])
            if not match:
                break
            start = idx + match.start()
            try:
                obj, end = decoder.raw_decode(text[start:])
                yield obj
                idx = start + end
            except Exception:
                idx = start + 1

    def parse_json(text: str):
        stripped = text.strip()
        if stripped.startswith("{") or stripped.startswith("["):
            try:
                return json.loads(stripped)
            except Exception:
                pass
        for obj in iter_json_objects(text):
            if isinstance(obj, (dict, list)):
                return obj
        return None

    data = parse_json(log)
    if data is not None:
        if isinstance(data, dict):
            if "testsuites" in data and isinstance(data["testsuites"], list):
                for suite in data["testsuites"]:
                    if isinstance(suite, dict):
                        walk_suite(suite)
            elif "testsuite" in data and isinstance(data["testsuite"], list):
                for suite in data["testsuite"]:
                    if isinstance(suite, dict):
                        walk_suite(suite, data.get("name", ""))
            else:
                walk_suite(data)
        elif isinstance(data, list):
            for item in data:
                if isinstance(item, dict):
                    walk_suite(item)
        if results:
            return results

    # XML fallback
    def parse_xml(text: str) -> bool:
        start_candidates = [text.find("<testsuites"), text.find("<testsuite")]
        start_candidates = [i for i in start_candidates if i >= 0]
        if not start_candidates:
            return False
        start = min(start_candidates)
        xml_text = text[start:]
        root = None
        try:
            root = ET.fromstring(xml_text)
        except Exception:
            try:
                root = ET.fromstring(f"<root>{xml_text}</root>")
            except Exception:
                return False

        for case in root.iter("testcase"):
            name = case.get("name", "")
            classname = case.get("classname") or case.get("class") or ""
            full_name = f"{classname}.{name}" if classname else name
            status = "pass"
            if case.find("skipped") is not None:
                status = "skip"
            if case.find("failure") is not None or case.find("error") is not None:
                status = "fail"
            record(full_name, status)
        return bool(results)

    if parse_xml(log):
        return results

    # Text-based fallbacks
    pytest_re = re.compile(r"^(?P<name>.+?::.+?)\s+(PASSED|FAILED|SKIPPED|XFAIL|XPASS|ERROR)\b", re.IGNORECASE)
    go_re = re.compile(r"^---\s+(PASS|FAIL|SKIP):\s+(\S+)")
    gtest_re = re.compile(r"^\[\s*(OK|FAILED|SKIPPED)\s*\]\s+([^\s]+)")
    unittest_re = re.compile(r"^(?P<name>[\w./:-]+)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)", re.IGNORECASE)
    jest_re = re.compile(r"^\s*(✓|✕|×|○)\s+(.+?)\s*$")

    status_map = {
        "PASSED": "pass",
        "PASS": "pass",
        "OK": "pass",
        "FAILED": "fail",
        "FAIL": "fail",
        "ERROR": "fail",
        "SKIPPED": "skip",
        "SKIP": "skip",
        "XFAIL": "skip",
        "XPASS": "fail",
    }

    for line in log.splitlines():
        line = line.rstrip()

        match = pytest_re.match(line)
        if match:
            name = match.group("name").strip()
            status_token = match.group(2).upper()
            record(name, status_map.get(status_token, "fail"))
            continue

        match = go_re.match(line)
        if match:
            status_token = match.group(1).upper()
            name = match.group(2).strip()
            record(name, status_map.get(status_token, "fail"))
            continue

        match = gtest_re.match(line)
        if match:
            status_token = match.group(1).upper()
            name = match.group(2).strip()
            record(name, status_map.get(status_token, "fail"))
            continue

        match = unittest_re.match(line)
        if match:
            name = match.group("name").strip()
            status_token = match.group(2).upper()
            record(name, status_map.get(status_token, "fail"))
            continue

        match = jest_re.match(line)
        if match:
            symbol = match.group(1)
            name = match.group(2).strip()
            if symbol == "✓":
                status = "pass"
            elif symbol == "○":
                status = "skip"
            else:
                status = "fail"
            record(name, status)
            continue

    return results
